    parts=re.split(r'\s*(?:,|&| and )\s*', str(s))
    return [p.strip() for p in parts if p.strip()]

# first-time winners by ceremony (if multiple composers, treat individuals)
seen=set(); firsts=[]
for _,r in df.sort_values('Year').iterrows():
    comps=split_composers(r['Composer'])
    new=[c for c in comps if c not in seen]
    if new:
        for c in new:
            firsts.append((r['Year'], c, r['Film']))
    for c in comps:
        seen.add(c)
print('First ceremony year:', df['Year'].min(), df.loc[df['Year'].idxmin(),'Composer'], df.loc[df['Year'].idxmin(),'Film'])
