    for c in split_composers(r['Composer']):
        rows.append((int(r['Year']),c))
exp=pd.DataFrame(rows, columns=['Year','Composer'])

max_gap=None
for comp,grp in exp.groupby('Composer'):
    years=sorted(grp['Year'].unique())
    if len(years)<2: continue
    for a,b in zip(years, years[1:]):
        gap=b-a
        if max_gap is None or gap>max_gap[0]:
